### Unit‑test sketch (using xUnit)

```csharp
using Xunit;
using System.Collections.Generic;

public class NumberUtilsTests
{
    [Fact]
    public void ReturnsSecondHighest_ForTypicalInput()
    {
        var data = new List<int> { 5, 1, 9, 3, 7 };
        Assert.Equal(7, NumberUtils.SecondHighest(data));
    }

    [Fact]
    public void HandlesDuplicates_Correctly()
    {
        var data = new List<int> { 4, 4, 2, 2, 8 };
        Assert.Equal(4, NumberUtils.SecondHighest(data));
    }

    [Fact]
    public void Throws_WhenAllElementsEqual()
    {
        var data = new List<int> { 5, 5, 5 };
        Assert.Throws<InvalidOperationException>(() => NumberUtils.SecondHighest(data));
    }

    [Fact]
    public void Throws_WhenListTooShort()
    {
        var data = new List<int> { 10 };
        Assert.Throws<InvalidOperationException>(() => NumberUtils.SecondHighest(data));
    }
}
```

These tests confirm the method behaves as intended without relying on any sorting utilities.
